package com.optarena.app

class SettingsStore {
    private val values = mutableMapOf(
        "theme" to "dark",
        "lang" to "en",
    )

    fun set(key: String, value: String) {
        values[key] = value
    }

    // Return the setting, or `default` when the key isn't present.
    // BUG: `!!` asserts the lookup is never null - a missing key throws
    // NullPointerException instead of falling back to the default.
    fun getOrDefault(key: String, default: String): String {
        return values[key]!!
    }
}

