package com.optarena.app

import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Test

class SettingsStoreHiddenTest {

    @Test
    fun presentKeyReturnsValue() {
        val store = SettingsStore()
        assertEquals("dark", store.getOrDefault("theme", "light"))
    }

    @Test
    fun missingKeyReturnsDefaultInsteadOfThrowing() {
        val store = SettingsStore()
        assertEquals("fallback", store.getOrDefault("nope", "fallback"))
    }

    @Test
    fun setThenGet() {
        val store = SettingsStore()
        store.set("timezone", "UTC")
        assertEquals("UTC", store.getOrDefault("timezone", "?"))
    }
}

